UPDATE course SET title = #{title}, student_id = #{studentId}, organization_id = #{organizationId},
subject = #{subject}, course_type = #{courseType}, start_time = #{startTime}, end_time = #{endTime},
fee = #{fee}, fee_manual = #{feeManual}, location = #{location}, note = #{note}, status = #{status},
color = #{color}, reminder_offset_minutes = #{reminderOffsetMinutes}
WHERE id = #{id} AND user_id = #{userId}
